description:
Design a debouncer circuit that stabilizes noisy input signals. This module synchronizes an input signal to a clock and only changes its output after confirming that the input has remained stable for a specified debounce period. The output transitions to reflect the stable state of the input signal after a defined debounce time, preventing false triggering due to signal fluctuations. The circuit uses a combination of time counters and state comparisons to ensure reliable signal integrity in applications such as button presses or switch contacts.
module top_module(
  input clk,        // Added clk input
  input in,
  output reg out    // Changed out to reg type
);

code:
module top_module(
  input clk,        // Added clk input
  input in,
  output reg out    // Changed out to reg type
);parameter clk_period = 10; // clock period in ns
parameter debounce_time = 50; // debounce time in ns

reg in_sync;
reg [31:0] stable_time;
reg [31:0] debounce_count;

always @(posedge clk) begin
  in_sync <= in;
  if (in_sync == out) begin
    stable_time <= stable_time + clk_period;
  end else begin
    stable_time <= 0;
  end
  if (stable_time >= debounce_time) begin
    debounce_count <= debounce_count + 1;
  end else begin
    debounce_count <= 0;
  end
  if (debounce_count >= 2) begin
    out <= in_sync;
  end
end

endmodule

