	wire temp1;
	wire temp2;
	wire temp3;
	wire temp4;
	wire temp5;
	wire temp6;
	wire temp7;
	wire temp8;
	wire temp9;
	wire temp10;
	wire temp11;
	wire temp12;

	input a;
	input b;	 
	input chave1;
	input chave2;

	assign temp1 = (~(a^b));
	assign temp2 = a^b;
	assign temp3 = (~(a|b));
	assign temp4 = a|b;
