  input reset; 
  output reg collide; 
  always @(posedge cclk or posedge reset) begin 
  if (cclk) begin 
  collide <= (bx >= px && bx <= (px + pw)) && (by+4 >= ptop && by-4 <= pbot); 
  end 
  else begin 
  collide <= 0; 
  end 
  end 
 endmodule

